use super::*;
fn put(c:&Connection,table:&str,v:&J)->R<()>{let obj=v.as_object().ok_or("Objeto inválido")?;let keys:Vec<&str>=obj.keys().map(String::as_str).collect();let q=format!("INSERT INTO {table} ({}) VALUES ({}) ON CONFLICT(id) DO UPDATE SET {}",keys.join(","),vec!["?";keys.len()].join(","),keys.iter().filter(|k|**k!="id").map(|k|format!("{k}=excluded.{k}")).collect::<Vec<_>>().join(","));exec(c,&q,&keys.iter().map(|k|obj[*k].clone()).collect::<Vec<_>>())?;Ok(())}
fn parse(v:&J,key:&str)->R<J>{serde_json::from_str(s(v,key)).map_err(|_|"Documento local inválido".into())}
fn envelope(kind:&str,p:J)->J{let area=if kind=="encounter"{p["kind"].clone()}else{p["area"].clone()};let patient=if kind=="patient"||kind=="bed"{J::Null}else if kind=="encounter"{p["patientId"].clone()}else{p["patient_id"].clone()};json!({"id":p["id"],"kind":kind,"area":area,"patient_id":patient,"reference_id":p["reference_id"],"payload":p})}
fn changed(mut old:J,fields:J)->J{let version=n(&old,"version")+1;old=with(old,fields);old["updated_at"]=json!(now());old["version"]=json!(version);old}
fn metadata(p:&J)->J{json!({"id":p["id"],"created_at":p["created_at"],"updated_at":p["updated_at"],"deleted_at":p["deleted_at"],"version":p["version"]})}
fn item(row:J)->R<J>{let values=parse(&row,"details")?;let mut p=row;p.as_object_mut().unwrap().remove("details");p["values"]=values;Ok(p)}
fn check_item(p:&J)->R<()>{let k=s(p,"kind");let expected=if ["bed","admission","kardex"].contains(&k){"Enfermería"}else{"Fisioterapia"};if !["bed","admission","kardex","routine","evolution"].contains(&k)||s(p,"area")!=expected{return Err("Tipo o área inválida".into());}let v=&p["values"];if !v.is_object()||v.as_object().unwrap().values().any(|x|x.as_str().map_or(true,|t|t.chars().count()>3000)){return Err("Valores inválidos".into());}
 let required=|key:&str,max:usize|->R<()>{if s(v,key).trim().is_empty()||s(v,key).chars().count()>max{Err(format!("Completa el campo {key}"))}else{Ok(())}};
 let date=|key:&str|->R<()>{let text=s(v,key);if chrono::NaiveDate::parse_from_str(text,"%Y-%m-%d").is_ok()||chrono::NaiveDateTime::parse_from_str(text,"%Y-%m-%dT%H:%M").is_ok()||chrono::DateTime::parse_from_rfc3339(text).is_ok(){Ok(())}else{Err(format!("Fecha inválida: {key}"))}};
 let number=|key:&str,min:f64,max:f64|->R<()>{let n=s(v,key).parse::<f64>().map_err(|_|"Número inválido")?;if n.is_finite()&&n>=min&&n<=max&&(key=="degrees"||n.fract()==0.0){Ok(())}else{Err(format!("Valor inválido: {key}"))}};
 match k{
 "bed"=>{required("code",24)?;required("ward",80)?;if !["Disponible","Mantenimiento"].contains(&s(v,"state")){return Err("Estado de cama inválido".into());}},
 "kardex"=>{for key in ["medication","dose","route","frequency"]{required(key,160)?;}date("scheduled_at")?;if !["Pendiente","Administrado","Omitido"].contains(&s(v,"state")){return Err("Estado de medicamento inválido".into());}if s(v,"state")=="Administrado"{date("administered_at")?;}},
 "admission"=>{date("admitted_at")?;required("reason",500)?;if !s(v,"discharged_at").is_empty(){date("discharged_at")?;if s(v,"discharged_at")<s(v,"admitted_at"){return Err("Alta anterior al ingreso".into());}}},
 "routine"=>{required("objective",1000)?;required("exercises",3000)?;required("frequency",100)?;date("start_date")?;date("end_date")?;if s(v,"end_date")<s(v,"start_date")||!["Activo","Completado","Suspendido"].contains(&s(v,"state")){return Err("Fechas o estado del plan inválidos".into());}},
 "evolution"=>{date("session_date")?;number("pain",0.0,10.0)?;number("degrees",0.0,360.0)?;number("daniels",0.0,5.0)?;required("progress",2000)?;},_=>{}
 }Ok(())}
impl Clinic{
 pub(super) fn seed_sync(&self)->R<()>{let c=&self.db;for kind in ["patient","encounter"]{let table=if kind=="patient"{"patients"}else{"encounters"};for row in rows(c,&format!("SELECT id FROM {table}"),&[])?{if one(c,"SELECT id FROM sync_state WHERE id=?",&[row["id"].clone()])?.is_null()&&one(c,"SELECT id FROM sync_outbox WHERE id=?",&[row["id"].clone()])?.is_null(){self.queue_doc(&self.doc(kind,s(&row,"id"))?)?;}}}Ok(())}
 fn doc(&self,kind:&str,key:&str)->R<J>{let c=&self.db;let p=if kind=="patient"{one(c,"SELECT * FROM patients WHERE id=?",&[json!(key)])?}else if kind=="encounter"{
  let e=one(c,"SELECT * FROM encounters WHERE id=?",&[json!(key)])?;if e.is_null(){return Ok(J::Null);}let values=if s(&e,"kind")=="Enfermería"{let v=one(c,"SELECT v.*,t.priority,t.notes FROM vital_signs v JOIN triage t ON t.vital_id=v.id WHERE v.encounter_id=?",&[json!(key)])?;json!({"temperatura":v["temperature"].to_string(),"pulso":v["pulse"].to_string(),"sistolica":v["systolic"].to_string(),"diastolica":v["diastolic"].to_string(),"saturacion":v["spo2"].to_string(),"triage":v["priority"],"observaciones":v["notes"]})}else{let v=one(c,"SELECT v.*,r.objective FROM evaluations v JOIN rehabilitation_plans r ON r.evaluation_id=v.id WHERE v.encounter_id=?",&[json!(key)])?;json!({"region":v["region"],"lado":v["side"],"movimiento":v["movement"],"grados":v["degrees"].to_string(),"daniels":v["daniels"].to_string(),"dolor":v["pain"].to_string(),"plan":v["objective"]})};with(e.clone(),json!({"patientId":e["patient_id"],"createdAt":e["created_at"],"author":e["author_name"],"values":values}))
 }else{let row=one(c,"SELECT * FROM clinical_items WHERE id=?",&[json!(key)])?;if row.is_null(){return Ok(J::Null);}item(row)?};if p.is_null(){Ok(J::Null)}else{Ok(envelope(kind,p))}}
 fn queue_doc(&self,d:&J)->R<()>{let state=one(&self.db,"SELECT revision FROM sync_state WHERE id=?",&[d["id"].clone()])?;let pending=json!({"id":d["id"],"op_id":id(),"doc":d,"base_revision":state["revision"].as_i64().unwrap_or(0),"created_at":now()});put(&self.db,"sync_outbox",&json!({"id":d["id"],"document":pending.to_string()}))}
 fn related_doc(&self,d:&J)->R<()>{let c=&self.db;let p=&d["payload"];let kind=s(d,"kind");if !d["patient_id"].is_null(){let patient=one(c,"SELECT * FROM patients WHERE id=? AND deleted_at IS NULL",&[d["patient_id"].clone()])?;if patient.is_null()||patient["area"]!=d["area"]{return Err("Paciente no disponible en esta área".into());}}
  if kind=="patient"&&!p["deleted_at"].is_null()&&!one(c,"SELECT id FROM clinical_items WHERE kind='admission' AND patient_id=? AND deleted_at IS NULL AND coalesce(json_extract(details,'$.discharged_at'),'')=''",&[d["id"].clone()])?.is_null(){return Err("Registra el alta hospitalaria primero".into());}
  if kind=="bed"&&(!p["deleted_at"].is_null()||s(&p["values"],"state")=="Mantenimiento")&&!one(c,"SELECT id FROM clinical_items WHERE kind='admission' AND reference_id=? AND deleted_at IS NULL AND coalesce(json_extract(details,'$.discharged_at'),'')=''",&[d["id"].clone()])?.is_null(){return Err("Cama con ingreso activo".into());}
  if ["admission","evolution"].contains(&kind)||kind=="routine"&&!d["reference_id"].is_null(){let reference=if kind=="routine"{one(c,"SELECT * FROM encounters WHERE id=? AND deleted_at IS NULL",&[d["reference_id"].clone()])?}else{one(c,"SELECT * FROM clinical_items WHERE id=? AND deleted_at IS NULL",&[d["reference_id"].clone()])?};if reference.is_null(){return Err("Referencia no disponible".into());}if kind=="admission"{if s(&reference,"kind")!="bed"||s(&parse(&reference,"details")?,"state")=="Mantenimiento"{return Err("Cama no disponible".into());}}else if reference["patient_id"]!=d["patient_id"]||(kind=="routine"&&s(&reference,"kind")!="Fisioterapia")||(kind=="evolution"&&s(&reference,"kind")!="routine"){return Err("Referencia clínica inválida".into());}}
  Ok(())
 }
 fn apply_doc(&self,d:&J,actor:&J)->R<()>{let c=&self.db;let p=&d["payload"];let kind=s(d,"kind");if !can_area(actor,s(d,"area"))||uuid::Uuid::parse_str(s(d,"id")).is_err()||p["id"]!=d["id"]||n(p,"version")<1{return Err("Documento o permiso inválido".into());}
  if (kind=="encounter"&&p["kind"]!=d["area"])||(kind!="encounter"&&p["area"]!=d["area"])||(kind!="patient"&&kind!="encounter"&&(p["kind"]!=d["kind"]||p["patient_id"]!=d["patient_id"]||p["reference_id"]!=d["reference_id"])) {return Err("Documento incoherente".into());}
  if kind=="patient"{check_patient(p)?;let mut fields=with(metadata(p),json!({"name":p["name"],"age":p["age"],"area":p["area"],"reason":p["reason"],"status":p["status"]}));if !p["legacy_id"].is_null(){fields["legacy_id"]=p["legacy_id"].clone();}return put(c,"patients",&fields);}
  if kind!="encounter"{check_item(p)?;let fields=with(metadata(p),json!({"kind":p["kind"],"area":p["area"],"patient_id":d["patient_id"],"reference_id":d["reference_id"],"details":p["values"].to_string(),"author":p["author"]}));return put(c,"clinical_items",&fields);}
  let old=one(c,"SELECT * FROM encounters WHERE id=?",&[d["id"].clone()])?;let fields=with(metadata(p),json!({"patient_id":d["patient_id"],"kind":d["area"],"author_id":if old.is_null(){actor["id"].clone()}else{old["author_id"].clone()},"author_name":p["author"]}));put(c,"encounters",&fields)?;let v=&p["values"];
  if !v.is_object()||v.as_object().unwrap().values().any(|x|x.as_str().map_or(true,|t|t.chars().count()>1000)){return Err("Valores clínicos inválidos".into());}
  let number=|k:&str,integer:bool|->R<J>{let n=s(v,k).parse::<f64>().map_err(|_|"Número inválido")?;if !n.is_finite()||integer&&n.fract()!=0.0{return Err("Número inválido".into());}Ok(if integer{json!(n as i64)}else{json!(n)})};
  let child=|table:&str,fields:J|->R<J>{let prior=one(c,&format!("SELECT * FROM {table} WHERE encounter_id=?"),&[d["id"].clone()])?;let base=if prior.is_null(){stamp()}else{metadata(&prior)};let mut value=with(base,fields);value["encounter_id"]=d["id"].clone();value["updated_at"]=p["updated_at"].clone();value["deleted_at"]=p["deleted_at"].clone();put(c,table,&value)?;Ok(value)};
  if s(d,"area")=="Enfermería"{let vit=child("vital_signs",json!({"temperature":number("temperatura",false)?,"pulse":number("pulso",true)?,"systolic":number("sistolica",true)?,"diastolic":number("diastolica",true)?,"spo2":number("saturacion",true)?}))?;child("triage",json!({"vital_id":vit["id"],"priority":v["triage"],"notes":s(v,"observaciones")}))?;}else{let ev=child("evaluations",json!({"region":v["region"],"side":v["lado"],"movement":v["movimiento"],"degrees":number("grados",false)?,"daniels":number("daniels",true)?,"pain":number("dolor",true)?}))?;child("rehabilitation_plans",json!({"evaluation_id":ev["id"],"objective":v["plan"]}))?;}Ok(())
 }
 fn save_conflict(&self,pending:&J,remote:&J,reason:&str)->R<()>{let conflict=json!({"id":pending["id"],"local":pending["doc"],"remote":remote,"reason":reason,"created_at":now()});put(&self.db,"sync_conflicts",&json!({"id":pending["id"],"document":conflict.to_string()}))?;let mut p=pending.clone();p["blocked"]=json!(true);put(&self.db,"sync_outbox",&json!({"id":p["id"],"document":p.to_string()}))}
 pub(super) fn week3(&self,op:&str,p:&J,actor:&J)->R<J>{let c=&self.db;
  if op=="clinical_data"{let mut result=vec![];for row in rows(c,"SELECT i.* FROM clinical_items i LEFT JOIN patients p ON p.id=i.patient_id WHERE i.deleted_at IS NULL AND (i.patient_id IS NULL OR p.deleted_at IS NULL)",&[])?{if can_area(actor,s(&row,"area")){result.push(item(row)?);}}return Ok(json!(result));}
  if ["patient_save","patient_delete","record_save","record_delete","item_save","item_delete"].contains(&op){let kind=if op.starts_with("patient"){"patient"}else if op.starts_with("record"){"encounter"}else{s(p,"kind")};if s(actor,"role_id")==ADMIN&&kind!="patient"{return Err("La atención clínica corresponde a Enfermería o Fisioterapia.".into());}let old=if s(p,"id").is_empty(){J::Null}else{self.doc(kind,s(p,"id"))?};if !s(p,"id").is_empty()&&(old.is_null()||!old["payload"]["deleted_at"].is_null()||old["payload"]["version"]!=p["version"]){return Err("Registro modificado o inexistente. Recarga.".into());}let fields=if op.ends_with("_delete"){json!({"deleted_at":now()})}else if kind=="patient"{json!({"name":s(p,"name").trim(),"age":p["age"],"area":p["area"],"reason":s(p,"reason").trim(),"status":p["status"]})}else if kind=="encounter"{json!({"patientId":p["patientId"],"kind":p["kind"],"values":p["values"],"author":if old.is_null(){actor["name"].clone()}else{old["payload"]["author"].clone()}})}else{json!({"kind":p["kind"],"area":p["area"],"patient_id":p["patient_id"],"reference_id":p["reference_id"],"values":p["values"],"author":if old.is_null(){actor["name"].clone()}else{old["payload"]["author"].clone()}})};let mut value=if old.is_null(){with(stamp(),fields)}else{changed(old["payload"].clone(),fields)};if kind=="encounter"{value["createdAt"]=value["created_at"].clone();}let d=envelope(kind,value.clone());if !old.is_null()&&(old["kind"]!=d["kind"]||old["area"]!=d["area"]||old["patient_id"]!=d["patient_id"]){return Err("Área y paciente originales son inmutables".into());}self.related_doc(&d)?;self.apply_doc(&d,actor)?;self.queue_doc(&d)?;return Ok(value);}
  if op=="sync_snapshot"{let mut pending=vec![];let mut count=0;for row in rows(c,"SELECT document FROM sync_outbox",&[])?{let p=parse(&row,"document")?;if can_area(actor,s(&p["doc"],"area")){count+=1;if p["blocked"]!=true{pending.push(p);}}}pending.sort_by_key(|p|{let k=s(&p["doc"],"kind");let rank=if !p["doc"]["payload"]["deleted_at"].is_null()&&n(p,"base_revision")>0&&["patient","bed"].contains(&k){9}else{match k{"patient"=>0,"bed"=>1,"encounter"=>2,"routine"=>3,_=>4}};(rank,s(p,"created_at").to_string())});pending.truncate(50);let mut conflicts=vec![];for row in rows(c,"SELECT document FROM sync_conflicts",&[])?{let v=parse(&row,"document")?;if can_area(actor,s(&v["local"],"area")){conflicts.push(v);}}let cursor=one(c,"SELECT value FROM meta WHERE key=?",&[json!(format!("cursor:{}",s(actor,"id")))])?;let last=one(c,"SELECT value FROM meta WHERE key=?",&[json!(format!("last-sync:{}",s(actor,"id")))])?;return Ok(json!({"pending":pending,"pending_count":count,"conflicts":conflicts,"cursor":s(&cursor,"value").parse::<i64>().unwrap_or(0),"last_sync":last["value"]}));}
  if op=="sync_apply"{
   for ack in p["acknowledgements"].as_array().ok_or("Confirmaciones inválidas")?{let row=one(c,"SELECT document FROM sync_outbox WHERE id=?",&[ack["id"].clone()])?;if row.is_null(){continue;}let mut pending=parse(&row,"document")?;if !can_area(actor,s(&pending["doc"],"area")){return Err("Área no autorizada".into());}let remote=&ack["document"];if s(ack,"status")=="conflict"{self.save_conflict(&pending,remote,"La versión del servidor cambió")?;continue;}put(c,"sync_state",&json!({"id":ack["id"],"revision":remote["revision"]}))?;if pending["op_id"]==ack["op_id"]{exec(c,"DELETE FROM sync_outbox WHERE id=?",&[ack["id"].clone()])?;}else{pending["base_revision"]=remote["revision"].clone();put(c,"sync_outbox",&json!({"id":pending["id"],"document":pending.to_string()}))?;}}
   for remote in p["changes"].as_array().ok_or("Cambios inválidos")?{if !can_area(actor,s(remote,"area")){return Err("Área remota no autorizada".into());}let state=one(c,"SELECT revision FROM sync_state WHERE id=?",&[remote["id"].clone()])?;if n(&state,"revision")>=n(remote,"revision"){continue;}let pending=one(c,"SELECT document FROM sync_outbox WHERE id=?",&[remote["id"].clone()])?;if !pending.is_null(){let pending=parse(&pending,"document")?;if pending["base_revision"]!=remote["revision"]{self.save_conflict(&pending,remote,"Servidor y equipo tienen cambios")?;}continue;}let old=self.doc(s(remote,"kind"),s(remote,"id"))?;let mut incoming=remote.clone();if !old.is_null(){insert(c,"sync_archive",&json!({"id":id(),"document":old.to_string(),"created_at":now()}))?;incoming["payload"]["version"]=json!(n(&old["payload"],"version")+1);}self.apply_doc(&incoming,actor)?;put(c,"sync_state",&json!({"id":remote["id"],"revision":remote["revision"]}))?;}
   for(key,value)in [(format!("cursor:{}",s(actor,"id")),p["cursor"].to_string()),(format!("last-sync:{}",s(actor,"id")),now())]{exec(c,"INSERT INTO meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",&[json!(key),json!(value)])?;}return Ok(json!({"ok":true}));
  }
  if op=="sync_resolve"{let row=one(c,"SELECT document FROM sync_conflicts WHERE id=?",&[p["id"].clone()])?;let conflict=parse(&row,"document")?;let pending=parse(&one(c,"SELECT document FROM sync_outbox WHERE id=?",&[p["id"].clone()])?,"document")?;if !can_area(actor,s(&pending["doc"],"area")){return Err("Conflicto no autorizado".into());}insert(c,"sync_archive",&json!({"id":id(),"document":json!({"conflict":conflict,"local":pending["doc"],"resolution":p["choice"]}).to_string(),"created_at":now()}))?;put(c,"sync_state",&json!({"id":p["id"],"revision":conflict["remote"]["revision"]}))?;
   if s(p,"choice")=="server"{let mut d=conflict["remote"].clone();d["payload"]["version"]=json!(n(&pending["doc"]["payload"],"version")+1);self.apply_doc(&d,actor)?;exec(c,"DELETE FROM sync_outbox WHERE id=?",&[p["id"].clone()])?;}else if s(p,"choice")=="local"{let mut d=pending["doc"].clone();d["payload"]=changed(d["payload"].clone(),json!({}));self.related_doc(&d)?;self.apply_doc(&d,actor)?;self.queue_doc(&d)?;}else{return Err("Resolución inválida".into());}exec(c,"DELETE FROM sync_conflicts WHERE id=?",&[p["id"].clone()])?;return Ok(json!({"ok":true}));
  }
  Err("Operación no admitida".into())
 }
}

